fn max_non_overlapping(mut ranges: Vec<(i32, i32)>) -> usize {
    ranges.sort_by_key(|range| range.1);
    let mut end = i32::MIN;
    ranges.into_iter().filter(|&(start, next_end)| {
        if start < end { false } else { end = next_end; true }
    }).count()
}

